//! Required Textarea disabled boolean reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><textarea id=select disabled=legacy>Seed</textarea><datalist id=choices><option id=suggestion>Suggestion</option></datalist><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://textarea-disabled.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn textarea_disabled_canonical_boolean_accessor_and_actual_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),P=HTMLTextAreaElement.prototype,a=Object.getOwnPropertyDescriptor(P,'disabled');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get disabled'||a.set.name!=='set disabled'||Object.hasOwn(x,'disabled')||x.disabled!==true||x.getAttribute('disabled')!=='legacy'||document.createElement('textarea').disabled!==false)throw 'canonical disabled boolean';"#);}
#[test]
fn textarea_disabled_native_boolean_conversion_identity_and_observer_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),old=x.getAttributeNode('disabled'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.disabled=false;var records=watch.takeRecords();if(x.disabled!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='disabled')throw 'false removes actual attribute';var calls=0;x.disabled={toString:function(){calls++;return '';},valueOf:function(){calls++;return 0;}};var attr=x.getAttributeNode('disabled');records=watch.takeRecords();if(calls||x.disabled!==true||attr===null||attr.value!==''||records.length!==1||records[0].oldValue!==null||document.getElementById('neighbor').value!=='seed')throw 'boolean conversion keeps actual record';x.disabled='';if(x.disabled!==false||attr.ownerElement!==null)throw 'empty string is false';"#);}
#[test]
fn textarea_disabled_inert_exact_namespace_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:textarea');if(!(x instanceof HTMLTextAreaElement)||x.disabled!==false)throw 'inert absent disabled';x.setAttributeNS('urn:foreign','disabled','foreign');x.setAttributeNS(null,'DISABLED','upper');if(x.disabled!==false)throw 'exact disabled namespace and case';x.disabled=true;var attr=x.getAttributeNodeNS(null,'disabled');if(x.disabled!==true||attr===null||attr.value!=='')throw 'inert actual boolean';x.removeAttributeNS('urn:foreign','disabled');x.removeAttributeNS(null,'DISABLED');var clone=x.cloneNode(false),copy=x.cloneNode(false);if(!(clone instanceof HTMLTextAreaElement)||!(copy instanceof HTMLTextAreaElement)||clone.disabled!==true||copy.disabled!==true||copy.ownerDocument!==doc||clone.getAttributeNode('disabled')===attr)throw 'independent boolean copies';clone.disabled=false;if(x.disabled!==true||copy.disabled!==true||clone.disabled!==false)throw 'independent disabled removal';"#);}

#[test]
fn textarea_disabled_truthiness_does_not_invoke_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),a=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'disabled'),calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.disabled!==false||x.hasAttribute('disabled'))throw 'false boolean value';}for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('boolean'),BigInt(1),author]){a.set.call(x,value);if(x.disabled!==true||x.getAttribute('disabled')!==''||calls)throw 'true boolean value';}a.set.call(x);if(x.disabled!==false||calls)throw 'missing boolean argument';"#);}



#[test]
fn textarea_disabled_brand_precedes_hooks_and_keeps_author_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),C=HTMLTextAreaElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'disabled'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('p'),document.createElement('ul'),document.createElement('li'),document.createElement('dl'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','textarea'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OL')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'disabled getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return '';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'disabled setter brand';}Object.defineProperty(x,'disabled',{value:'author',writable:true,configurable:true});a.set.call(x,false);if(x.disabled!=='author'||x.hasAttribute('disabled'))throw 'canonical attribute authority';delete x.disabled;if(x.disabled!==false||Object.hasOwn(x,'disabled'))throw 'restored inherited boolean';delete window.HTMLTextAreaElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved canonical interface';"#);}

#[test]
fn textarea_disabled_raw_attribute_aliases_observe_presence_and_preserve_exact_backing(){let(mut d,mut f,mut p)=fixture();for inert in [false,true]{run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','textarea');x.disabled=true;"}else{"var x=document.getElementById('select');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('disabled'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var key of ['value','nodeValue','textContent']){a[key]='R\ud800'+key;if(x.disabled!==true||a.value!=='R\ud800'+key||x.getAttributeNode('disabled')!==a)throw 'raw boolean backing';}var old=a.value;x.disabled=true;var records=watch.takeRecords();if(x.disabled!==true||a.value!==''||records.length!==4||records[3].oldValue!==old||x.getAttributeNode('disabled')!==a)throw 'boolean normalization uses current Attr';x.removeAttribute('disabled');if(x.disabled!==false||a.ownerElement!==null)throw 'actual boolean removal';x.setAttributeNS('urn:foreign','disabled','foreign');x.setAttributeNS(null,'DISABLED','upper');if(x.disabled!==false)throw 'exact disabled authority';x.setAttributeNS(null,'disabled','A\udfffZ');if(x.ownerDocument!==document){var clone=x.cloneNode(false);if(!x.disabled||!clone.disabled||clone.getAttributeNodeNS(null,'disabled').value!=='A\udfffZ'||clone.getAttributeNodeNS(null,'disabled')===x.getAttributeNodeNS(null,'disabled'))throw 'raw presence copy';}"#);}}

#[test]
fn textarea_disabled_saved_child_origin_refuses_before_observation_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLTextAreaElement.prototype,'disabled');a.set.call(x,false);if(a.get.call(x)!==false)throw 'same origin boolean';");p.set_location(&crate::navigation::address("https://other-disabled.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,true);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://textarea-disabled.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(x.disabled!==false)throw 'origin refusal preserves value';a.set.call(x,true);if(!a.get.call(x)||x.getAttribute('disabled')!=='')throw 'saved boolean recovery';");}


#[test]
fn textarea_disabled_writer_resource_refusal_is_atomic_and_recovers(){for inert in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','textarea');"}else{"var x=document.getElementById('select');x.disabled=false;"});run(&mut d,&mut f,&mut p,"var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let controls=f.controls.iter().map(|(n,c)|(*n,c.disabled,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value,c.name.clone(),c.required,c.readonly)).collect::<Vec<_>>();let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("x.disabled=true;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.disabled,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value,c.name.clone(),c.required,c.readonly)).collect::<Vec<_>>(),controls);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.disabled!==false||watch.takeRecords().length)throw 'atomic disabled refusal';x.disabled=true;var records=watch.takeRecords();if(x.disabled!==true||x.getAttribute('disabled')!==''||records.length!==1||records[0].oldValue!==null)throw 'fresh boolean recovery';");}}}

#[test]
fn textarea_disabled_reads_charge_names_work_and_deadline_without_string_copy_or_retained_growth(){for inert in [false,true]{for mode in 0..3{let(mut d,mut f,mut p)=fixture();let object=if inert{let Value::Host(object)=p.runtime.execute("var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','textarea');x.disabled=true;x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert SELECT")};object}else{node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap())};let before=format!("{:?}",d.nodes);let retained=p.state.retained;let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.retained_limit=retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_disabled_get(object);if mode==2{assert!(matches!(result,Ok(Value::Bool(true))));}else{assert!(result.is_err());}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_disabled_get(object),Ok(Value::Bool(true))));}}}


#[test]
fn textarea_disabled_fieldset_effective_state_stays_separate_from_own_reflection(){let mut d=crate::html::parse("<form id=form><fieldset disabled><legend><textarea id=exempt>One</textarea></legend><textarea id=blocked>Two</textarea></fieldset></form>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var a=document.getElementById('exempt'),b=document.getElementById('blocked');if(a.disabled||b.disabled)throw 'own presence only';b.disabled=true;b.disabled=false;a.disabled=true;");let exempt=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("exempt")).unwrap();let blocked=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("blocked")).unwrap();assert!(f.controls[&exempt].disabled);assert!(f.controls[&blocked].disabled);run(&mut d,&mut f,&mut p,"a.disabled=false;if(a.disabled||b.disabled)throw 'fieldset reflection';");assert!(!f.controls[&exempt].disabled);assert!(f.controls[&blocked].disabled);}

#[test]
fn textarea_disabled_native_dirty_editor_default_flags_and_events_stay_intact(){let(mut d,mut f,mut p)=fixture();let area=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select'),events=0;x.oninput=function(){events++;};x.onchange=function(){events++;};x.value='Dirty editor';");{let c=f.controls.get_mut(&area).unwrap();c.value.cursor=5;c.value.anchor=2;c.value.offset=1;}let c=&f.controls[&area];let before=(c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.caption.clone(),c.name.clone(),c.required,c.readonly,c.dirty_value);assert!(c.disabled&&c.dirty_value);for source in ["x.disabled=false;","x.disabled=true;","x.setAttributeNS(null,'disabled','R\\ud800Z');","x.getAttributeNode('disabled').value='changed';","x.removeAttribute('disabled');"]{p.begin_job();run(&mut d,&mut f,&mut p,source);let c=&f.controls[&area];assert_eq!((c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.caption.clone(),c.name.clone(),c.required,c.readonly,c.dirty_value),before);assert_eq!(c.disabled,d.dom_attr(area,"disabled").is_some());run(&mut d,&mut f,&mut p,"if(x.value!=='Dirty editor'||x.defaultValue!=='Seed'||x.firstChild.textContent!=='Seed'||events)throw 'disability preserves editor/default/events';");}}
#[test]
fn textarea_disabled_native_validation_submission_script_edit_and_reset(){let mut d=crate::html::parse("<form id=form><textarea id=area name=q required></textarea></form>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://textarea-disabled.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let area=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("area")).unwrap();assert!(f.validate_submission(&d,owner,None).is_err());run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.disabled=true;x.value='Edited';");assert!(f.controls[&area].disabled);assert!(f.validate_submission(&d,owner,None).is_ok());assert_eq!(f.script_submit_request(&d,owner,&location,&location).unwrap().location.url.unwrap().query.as_deref().unwrap_or(""),"");run(&mut d,&mut f,&mut p,"x.disabled=false;if(x.value!=='Edited'||x.defaultValue!=='')throw 'disabled script editing remains allowed';");assert_eq!(f.script_submit_request(&d,owner,&location,&location).unwrap().location.url.unwrap().query.as_deref(),Some("q=Edited"));run(&mut d,&mut f,&mut p,"x.disabled=true;");f.reset_in_document(&d,owner).unwrap();assert!(f.controls[&area].disabled);assert!(!f.controls[&area].dirty_value);assert!(f.validate_submission(&d,owner,None).is_ok());run(&mut d,&mut f,&mut p,"if(x.value!==''||!x.disabled)throw 'native reset retains disabled';x.disabled=false;");assert!(f.validate_submission(&d,owner,None).is_err());}
